create schema private;create role anon;create role authenticated;create role service_role;set check_function_bodies=off;
create table private.fee_rate_versions(id uuid,country text,rule_key text);create table private.fee_rate_current_evidence(version_id uuid,rule_key text,generation_id uuid,source_id uuid,state text,direction text);create table private.fee_rate_generations(id uuid,published_at timestamptz);create table public.third_party_rates(id uuid,country text,category text,third_party text,updated_at timestamptz);
create table private.dashboard_admin_provider_registry(country text,platform text,raw_provider text,canonical_values jsonb);create table private.dashboard_admin_provider_overrides(country text,platform text,raw_provider text,canonical_provider text,version int);create table private.dashboard_admin_order_provider_confirmations(source_system text,country_code text,platform text,order_kind text,order_no text,confirmed_provider text,active boolean);create table public.ar_config_targets(source_system text,country_code text,platform text,currency text);
create function private.dashboard_data_group(text,text)returns text language sql immutable as $$select $1$$;